"""Contrast detector: fires on "but" / "however" and on the words just after them.

Component p-82af68dd@100000/layers.15.mlp.down_proj:1730 (layer 15 MLP output) writes
into the residual stream at a contrast: a clause-level contrastive conjunction such as
"but", "However", "pero", "aber", "但", "しかし", "但是". It is strongest on the
conjunction itself, and it carries on for a few tokens after it, fading by a fixed
factor per token (the subject that follows "But", then the next word).

How strong the conjunction is depends on what comes before it and on the word itself:
- after punctuation, a clause boundary (", but", ". However", "; but"): strongest;
- after a line break: a little weaker;
- after an ordinary word: weaker;
- after an idiomatic word, as in "can't help but", "nothing but", "not ... but",
  "all but", "even ... but": nearly silent, since it is not a contrast.
Words differ too: "but" and "however" (and their translations) are strong, "yet" and
"nevertheless" medium, while "though", "although", "whereas", and "ma", "ale", "mas",
"но" (which are weaker or ambiguous) are weak.

Program: look back up to WINDOW tokens in the same document for the nearest contrast
word, at distance k. Its value is the level set by the token before it, times the
word's strength, times DECAY**k. Otherwise predict 0.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# How strongly each word signals a contrast (1 = "but").
STRONG = {
    "but", "however", "pero", "maar", "nhưng", "但", "但是", "しかし", "然而", "однако",
    "ولكن", "لكن", "하지만", "だが", "aber", "mais",
}
MEDIUM = {"yet", "doch", "nevertheless", "nonetheless", "不过", "可是", "けど", "그러나"}
WEAK = {"though", "although", "whereas", "ma", "ale", "mas", "но"}
STRENGTH = {**dict.fromkeys(STRONG, 1.0), **dict.fromkeys(MEDIUM, 0.5), **dict.fromkeys(WEAK, 0.15)}

# Words that make a "but" idiomatic rather than a contrast.
IDIOM_BEFORE = {"help", "nothing", "all", "anything", "not", "even"}

# Activation on a strong contrast word, by the kind of token just before it.
PUNCT_LEVEL = 12.0  # after punctuation: a clause boundary
LINE_LEVEL = 9.4  # after a line break
WORD_LEVEL = 5.4  # after an ordinary word
IDIOM_LEVEL = 1.3  # after an idiomatic word ("help but")
DECAY = 0.37  # factor per token after the contrast word
WINDOW = 6  # tokens looked back

PUNCT = re.compile(r"\s*[^\w\s]+\s*")


def _word(text: str) -> str:
    return text.strip().lower()


def _level(prev: str) -> float:
    """Activation on a strong contrast word whose previous token is `prev`."""
    if _word(prev) in IDIOM_BEFORE:
        return IDIOM_LEVEL
    if "\n" in prev:
        return LINE_LEVEL
    if PUNCT.fullmatch(prev):
        return PUNCT_LEVEL
    return WORD_LEVEL


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    docs, words = prefix.document_ids, prefix.token_strings
    for k in range(min(WINDOW, t + 1)):
        i = t - k
        if docs[i] != docs[t]:
            break  # a new document starts here: no contrast carries over
        word = _word(words[i])
        if word in STRENGTH:
            prev = words[i - 1] if i >= 1 and docs[i - 1] == docs[i] else ""
            return carry, _level(prev) * STRENGTH[word] * DECAY**k
    return carry, 0.0

"""A retrospective-versus-prospective word feature, for layers.15.mlp.down_proj component 1733.

The component's activation is almost entirely a read of one MLP hidden unit of layer 15
(unit 1733, about 0.79 of its weight), so it is negative where that unit is negative.
Its output direction, read through the unembedding, pushes toward past-outcome words
("outcome", "results", "survived", "lasted") when the activation is negative, and toward
prospective words ("will", "chance", "potential", "prospect") when it is positive.

On training text the activation is most negative in retrospective phrases about elapsed
time and results: duration words ("for several years", "decades", "months", "ago", "past"),
"since", "now", "already", "已经", the perfect "been"/"has"/"have" (strongest in "I've been",
"it's been"), and success words ("success", "accomplishments"). It is mildly positive on
"did", "earlier", "once", "recently" and "sooner", and mildly negative on "will", "chance"
and "potential".

This program predicts those word-level values and 0 elsewhere. It explains only about
0.2% of the activation's variance. The activation is spread thinly over most tokens, and
its sign depends on context this program does not model, so the words here are a weak
signal and not the component's main job.
"""

READS = ()

DURATION = {"years", "year", "decades", "decade", "months", "ago", "centuries", "past", "年", "年来", "年间", "多年", "个月"}
RECENT = {"since", "now", "already", "已经", "已"}
PERFECT = {"been", "has", "have", "had"}
SUCCESS = {"success", "successful", "accomplishments"}
PAST_EVENT = {"did", "earlier", "once", "recently", "recent", "sooner", "former"}
FUTURE = {"will", "chance", "chances", "potential", "prospect", "plans", "expect", "upcoming"}
CONTRACTED = {"'ve", "'s"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().replace("’", "'")
    before = prefix.token_strings[-2].strip().lower().replace("’", "'") if len(prefix.token_ids) > 1 else ""
    if word == "been" and before in CONTRACTED:
        value = -1.3
    elif word in DURATION:
        value = -0.35
    elif word in SUCCESS:
        value = -0.23
    elif word in RECENT:
        value = -0.22
    elif word in PERFECT:
        value = -0.13
    elif word in PAST_EVENT:
        value = 0.2
    elif word in FUTURE:
        value = -0.13
    else:
        value = 0.0
    return carry, value

"""Place-name slot detector (layer 15 MLP, component 1737).

What it does: this component fires on the word just BEFORE a place name the
model expects to come next, e.g. the "in" of "based in [New York]", the "of" of
"Mayor of [Galena]", the "the" of "across the [United States]", or the
"North" of "[North] Carolina". Its activation is large and positive at those
slots and near zero or negative elsewhere.

The program is a hand-written guess at that slot, from the words in front:
  * a geographic name-modifier (North, South, New, San, Santa, United, ...): 2.5
  * a locative preposition (in, at, on, from, of, and the same words in other
    languages: в, en, à, dans, im, auf, 在) : 1.0 for "in", 0.6 for other
    foreign locatives, 0.5 for "at", 0.25 for "on"/"from"/others, 0.1 for "of"
  * the same preposition right after a place cue (based, born, living, located,
    resident, village, City, State, University, Mayor, ...): 3.0
  * a determiner (the, this, our, ...) right after a locative preposition: 0.6,
    or 2.5 after a "surrounding" word (across, throughout, around, within, outside)
  * everything else: 0.
Predictions use only the tokens so far in the same document.
"""

READS = ()

LOC_PREP = {"in", "at", "on", "from", "of", "across", "throughout", "around", "within", "outside", "near", "into", "over", "through", "during"}
FOREIGN_LOC = {"в", "на", "во", "en", "à", "dans", "im", "auf", "在", "于"}
PLACE_CUE = {"based", "born", "living", "lived", "live", "lives", "died", "located", "established", "resident", "residents",
             "headquartered", "village", "town", "city", "County", "State", "District", "Province", "University", "School",
             "President", "Mayor", "Governor", "north", "south", "east", "west", "middle", "heart", "coast", "parts", "regions",
             "people", "here", "held", "Republic", "capital"}
DETERMINERS = {"the", "this", "our", "your", "my", "that", "their", "his", "her", "these", "its"}
GEO_MODIFIERS = {"North", "South", "East", "West", "Northern", "Southern", "Eastern", "Western", "New", "San", "Santa", "Los",
                 "Las", "Puerto", "Saint", "Fort", "Lake", "Mount", "United", "Central", "Upper", "Lower", "Great", "Sierra"}
STRONG_LOC = {"across", "throughout", "around", "within", "outside"}
BASE = {"in": 1.0, "at": 0.5, "on": 0.25, "from": 0.25, "of": 0.1}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if cur in GEO_MODIFIERS:
        return None, 2.5
    if cur in FOREIGN_LOC:
        return None, 3.0 if prev in PLACE_CUE else 0.6
    if cur in LOC_PREP:
        if prev in PLACE_CUE:
            return None, 3.0
        return None, BASE.get(cur, 0.25)
    if cur in DETERMINERS and prev in STRONG_LOC:
        return None, 2.5
    if cur in DETERMINERS and prev in LOC_PREP:
        return None, 0.6
    return None, 0.0

"""Layer 15, MLP hidden unit 1751: the component's main direction, read off by token class.

What it is: nearly all of this component (its input direction puts 0.71 on MLP hidden unit
1751 of layer 15) is one MLP neuron. Its value is diffuse. Neither the token's identity, its
neighbours, its document, nor any word-level concept explains more than about 1% of its
variance. The only regularities found are weak class means: digits lean positive;
punctuation, line breaks and code or markup symbols lean negative. This program predicts
those class means from the newest token's text, and nothing else.
"""

READS = ()

MARKUP = set('{}[]<>"=/\\_|')

# Mean activation of each token class, measured on 2M training tokens.
MEAN = {
    "newline": -0.024,
    "markup": -0.019,
    "digit": 0.020,
    "han": 0.0,
    "word": 0.008,
    "punct": -0.027,
    "other": -0.003,
}


def token_class(text):
    if "\n" in text:
        return "newline"
    if MARKUP & set(text):
        return "markup"
    if text.strip().isdigit():
        return "digit"
    if any("一" <= c <= "鿿" for c in text):
        return "han"
    if text.strip().isalpha() and text.isascii():
        return "word"
    if text.strip() and not any(c.isalnum() for c in text):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    return carry, MEAN[token_class(prefix.token_strings[-1])]

"""Layer 15, MLP hidden unit 1764 (its component's main input) as a weak lexical tendency.

The component's input is mainly MLP hidden unit 1764 of layer 15, scaled by a fixed norm.
Its activation is mostly near zero, with a heavy negative tail. Token identity and short
context explain very little of it: a lookup of token means, and a small window-based network,
both fail to generalise. So this program only nudges the prediction by the average value of a
few word classes seen in the data:

- commas (and the full-width comma) lean negative;
- clause-linking words (so, to, for, that, which, because, and their Japanese and Chinese
  equivalents) lean negative;
- modal and helper words (can, will, may, might, help, but, also, or) lean slightly positive;
- digits and sentence stops lean slightly positive.

Every other token predicts 0.
"""

READS = ()

COMMAS = {",", "，", "、"}
CONNECTIVES = {" so", " to", " for", " that", " which", " because", "ので", "ため", "して", "所以"}
MODALS = {" can", " will", " may", " might", " would", " could", " must", " help", " helps", " but", " also", " or"}
DIGITS = set("0123456789")
STOPS = {".", ".\n", "\n", "\n\n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in COMMAS:
        value = -0.12
    elif tok in CONNECTIVES:
        value = -0.09
    elif tok in MODALS:
        value = 0.09
    elif tok in DIGITS or tok in STOPS:
        value = 0.03
    else:
        value = 0.0
    return carry, value

"""Verb-expecting slot detector for p-82af68dd@100000/layers.15.mlp.down_proj:1766.

This component writes into the residual stream when the model is at a word after
which a bare verb is expected next: the infinitive 'to' ('need to make', 'designed
to'), a modal ('can', 'will'), a subject pronoun ('they', 'he', 'who', 'which').
Its size is set by the word group, as the mean activation of that group on sample text.
A prepositional 'to' ('due to', 'according to', 'related to') does not fire, and the
forms of 'be' and the determiners push it slightly negative, since a noun or
adjective follows them rather than a verb.
"""
READS = ()

# words that take an infinitive: 'to' after them is followed by a verb
INFINITIVE_HINTS = {'need', 'needs', 'want', 'wants', 'used', 'designed', 'required', 'how', 'going',
                    'have', 'has', 'had', 'is', 'able', 'unable', 'ability', 'time', 'order', 'way',
                    'continue', 'continues', 'plans', 'trying', 'try', 'tried', 'seems', 'ready', 'you', 'him', 'us', 'them'}
# words that take a prepositional 'to': 'to' after them is followed by a noun
PREPOSITION_TO_HINTS = {'due', 'up', 'according', 'equal', 'compared', 'related', 'back', 'connected', 'similar',
                        'prior', 'next', 'close', 'respond', 'belong', 'addition', 'from', 'access', 'attention',
                        'referred', 'relating', 'attached', 'added', 'equivalent', 'parallel', 'leads', 'lead'}
MODALS = {'can', 'will', 'would', 'could', 'should', 'may', 'might', 'must', 'shall'}
SUBJECT_PRONOUNS = {'they', 'he', 'she', 'we', 'who', 'which'}
OTHER_PRONOUNS = {'you', 'it', 'i'}
LINK_WORDS = {'and', 'by', 'also', 'not', 'have', 'has', 'that'}
BE_FORMS = {'is', 'be', 'was', 'were', 'are', 'am', 'been', 'being'}
DETERMINERS = {'the', 'a', 'an', 'this', 'these', 'those'}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ''
    if word == 'to':
        if before in PREPOSITION_TO_HINTS:
            return None, 0.0
        if before in INFINITIVE_HINTS:
            return None, 3.3
        return None, 2.4
    if word in MODALS:
        return None, 2.3
    if word in SUBJECT_PRONOUNS:
        return None, 2.4
    if word in OTHER_PRONOUNS:
        return None, 0.8
    if word in LINK_WORDS:
        return None, 0.6
    if word in BE_FORMS:
        return None, -0.6
    if word in DETERMINERS:
        return None, -0.1
    return None, 0.0

"""Predict the average activation, higher on hedging words (maybe, perhaps, likely, seems, might),
where the component is on average positive, and about 0 at the first token of each document."""

READS = ()

MEAN_ACTIVATION = 0.058
HEDGES = {"maybe": 0.3, "perhaps": 0.3, "likely": 0.6, "seems": 0.6, "might": 0.2, "probably": 0.1, "think": 0.1}


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    if len(doc) == 1 or doc[-1] != doc[-2]:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    return None, HEDGES.get(word, MEAN_ACTIVATION)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:1786 (layer 15 MLP, one of its down-projection pieces).

Plain-terms reading: a "passive or copular predicate is coming" feature. Its output direction
promotes information-status words after the verb (known, unknown, suspected, inferred,
confirmed, rumored, likely), so it is strongest where a claim's status is about to be stated.

Rules, in order of strength:
- A form of "be" (is, are, was, were, be, been, being) that opens a predicate is high:
  about 2.6 right after a modal, "have" or "to" ("can be", "has been", "to be"), 1.7 by
  default, and about 0.8 after a question word, demonstrative or pronoun subject ("what is", "this is", "I am").
- An adverb or negator right after a be-form, before the predicate, is high (about 2.2):
  "is [not] known", "was [also] found", "is [often] cited", "are [typically] used".
  After a modal or "have" these do not fire.
- Information-status words are mildly positive ("evidence", "known", "unclear", "appears",
  "seems"), and speculation words are negative ("probably", "maybe", "perhaps", "possibly",
  "likely", "suppose", "might", "would", "could").
- Everywhere else, including the first token of a document, it is zero.

Honest limits: this captures the sign and location of the strongest events, not most of the
variance. Most of its activation is small, diffuse and not predictable from the previous token,
so the program explains about 11% of the variance (Pearson r about 0.34), and switching it off
or replacing it by this program changes the model's output by similar amounts. The program reads
only the current token and the one before it, within the same document.
"""

READS = ()

BE = {"is", "are", "was", "were", "be", "been", "being"}
BEFORE_STRONG = {"can", "may", "must", "should", "will", "could", "would", "might", "shall",
                 "cannot", "has", "have", "had", "to"}
BEFORE_WEAK = {"what", "this", "that", "there", "problem", "answer", "question", "i", "you", "we"}
ADV_AFTER_BE = {"not", "also", "often", "widely", "typically", "commonly", "generally",
                "usually", "never", "only", "still", "now", "previously", "again", "already"}
INFO = {"evidence": 1.0, "known": 1.0, "unknown": 0.8, "unclear": 2.0, "appears": 1.2,
        "seems": 0.9, "reported": 0.6}
SPECULATIVE = {"probably": -1.0, "maybe": -0.7, "perhaps": -0.5, "possibly": -0.6,
               "likely": -0.6, "suppose": -0.7, "might": -0.3, "would": -0.4, "could": -0.2}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0  # first token of a document: nothing to read yet
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower()
    if cur in BE:
        if prev in BEFORE_STRONG:
            value = 2.6
        elif prev in BEFORE_WEAK:
            value = 0.8
        else:
            value = 1.7
    elif cur in ADV_AFTER_BE and prev in BE:
        value = 2.2
    elif cur in INFO:
        value = INFO[cur]
    elif cur in SPECULATIVE:
        value = SPECULATIVE[cur]
    elif cur == "also":
        value = 0.8
    else:
        value = 0.0
    return carry, value
